//! Materializes the exact boot artifacts generated by this system's build.

use std::path::{Path, PathBuf};
use std::process::ExitCode;

const ASSETS: &[(&str, &[u8])] = &[
    (
        "stage0.v3bin",
        include_bytes!(concat!(env!("OUT_DIR"), "/stage0.v3bin")),
    ),
    (
        "stage1.v3bin",
        include_bytes!(concat!(env!("OUT_DIR"), "/stage1.v3bin")),
    ),
    (
        "boot-demo.v3bin",
        include_bytes!(concat!(env!("OUT_DIR"), "/boot-demo.v3bin")),
    ),
    (
        "boot-alt.v3bin",
        include_bytes!(concat!(env!("OUT_DIR"), "/boot-alt.v3bin")),
    ),
    (
        "data.bin",
        include_bytes!(concat!(env!("OUT_DIR"), "/data.bin")),
    ),
    (
        "cpu-v3-boot.bin",
        include_bytes!(concat!(env!("OUT_DIR"), "/cpu-v3-boot.bin")),
    ),
    (
        "cpu-v3-boot.map",
        include_bytes!(concat!(env!("OUT_DIR"), "/cpu-v3-boot.map")),
    ),
];

fn main() -> ExitCode {
    match run(std::env::args_os().skip(1)) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("cpu-v3-boot-assets: error: {error}");
            ExitCode::FAILURE
        }
    }
}

fn run(mut args: impl Iterator<Item = std::ffi::OsString>) -> Result<(), String> {
    let first = args.next();
    if first.as_deref() == Some(std::ffi::OsStr::new("-h"))
        || first.as_deref() == Some(std::ffi::OsStr::new("--help"))
    {
        println!("usage: cpu-v3-boot-assets [OUTPUT-DIRECTORY]");
        return Ok(());
    }
    let output = first
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("target/cpu-v3-boot"));
    if let Some(argument) = args.next() {
        return Err(format!(
            "unexpected argument `{}`; usage: cpu-v3-boot-assets [OUTPUT-DIRECTORY]",
            argument.to_string_lossy()
        ));
    }

    std::fs::create_dir_all(&output)
        .map_err(|error| format!("cannot create {}: {error}", output.display()))?;
    for (name, bytes) in ASSETS {
        write_if_changed(&output.join(name), bytes)?;
    }
    write_if_changed(
        &output.join("boot-assets.manifest"),
        asset_manifest().as_bytes(),
    )?;
    println!(
        "materialized {} generated CPU V3 boot artifacts -> {}",
        ASSETS.len(),
        output.display()
    );
    Ok(())
}

fn write_if_changed(path: &Path, bytes: &[u8]) -> Result<(), String> {
    if std::fs::read(path).ok().as_deref() == Some(bytes) {
        return Ok(());
    }
    std::fs::write(path, bytes).map_err(|error| format!("cannot write {}: {error}", path.display()))
}

fn asset_manifest() -> String {
    let mut manifest = String::from("format=1\n");
    for (name, bytes) in ASSETS {
        manifest.push_str(&format!(
            "asset={name} bytes={} fnv1a64={:016x}\n",
            bytes.len(),
            fnv1a64(bytes)
        ));
    }
    manifest
}

fn fnv1a64(bytes: &[u8]) -> u64 {
    bytes.iter().fold(0xcbf2_9ce4_8422_2325, |hash, byte| {
        (hash ^ u64::from(*byte)).wrapping_mul(0x100_0000_01b3)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_assets_include_the_baselined_flash_package() {
        let package = ASSETS
            .iter()
            .find(|(name, _)| *name == "cpu-v3-boot.bin")
            .unwrap()
            .1;
        assert_eq!(package.len(), 2_563);
        assert_eq!(fnv1a64(package), 17_504_881_831_299_992_042);
        assert!(asset_manifest().contains("asset=stage0.v3bin"));
        assert!(asset_manifest().contains("asset=cpu-v3-boot.map"));
    }
}
